const $=s=>document.querySelector(s),app=$('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>v==null||!Number.isFinite(v)?'—':v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const pct=v=>v==null?'—':num(v*100,1)+'%';
const sign=v=>v==null?'—':(v>0?'+':'')+num(v,0);
const slugify=s=>s.replace(/[Øø]/g,'o').replace(/[Ææ]/g,'ae').replace(/[Œœ]/g,'oe').replace(/ß/g,'ss').replace(/[Łł]/g,'l').replace(/[ĐđÐð]/g,'d').replace(/[Þþ]/g,'th').replace(/ı/g,'i').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/['’`.]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,70).replace(/-+$/g,'');
const ROLES={Top:'上单',Jungle:'打野',Mid:'中单',Bot:'下路',Support:'辅助'},ROLECODE={T:'Top',J:'Jungle',M:'Mid',B:'Bot',S:'Support'},SHORT={Top:'TOP',Jungle:'JGL',Mid:'MID',Bot:'ADC',Support:'SUP'};
