const icon=(name)=>`<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${({search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',players:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m0-17a3 3 0 0 1 0 6m4 11v-3a6 6 0 0 0-3-5"/>',chart:'<path d="M4 20h17M7 16V9m6 7V4m6 12v-5"/>',cup:'<path d="M7 3h10v6a5 5 0 0 1-10 0V3ZM7 5H3v3a4 4 0 0 0 5 4m9-7h4v3a4 4 0 0 1-5 4m-4 2v6m-4 1h8"/>',compare:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'})[name]||''}</svg>`;
function storage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
const state={q:'',role:'',region:'',scope:'all',sort:'g',asc:false,page:1,year:String(CURRENT_YEAR),eventsQ:'',eventPage:1,tab:'overview',historyYear:'all',detailEvent:'',detailSlug:'',compare:storage('rift-compare',[]).slice(0,2),saved:storage('rift-saved',[]),compareEvent:'worlds-2026',teamQ:'',match:{year:String(CURRENT_YEAR),league:'all',event:'all',status:'all',q:'',page:1}};
