let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function saveState(){try{localStorage.setItem('rift-compare',JSON.stringify(state.compare));localStorage.setItem('rift-saved',JSON.stringify(state.saved));}catch{}}
const photo=(slug)=>D.profiles[slug]?.photo||(D.archive.photos[slug]?`https://riftwise.gg/stats/photos/${encodeURIComponent(slug)}.webp`:D.profiles[slug]?.img?.replace('http:','https:'))||'assets/player-placeholder.svg';
const portrait=(slug,cls='player-photo')=>`<img class="${cls}" src="${esc(imageUrl(photo(slug)))}" alt="${esc(D.profiles[slug]?.name||INDEX.find(p=>p.u===slug)?.n||slug)} 选手头像" loading="lazy" data-fallback="player">`;
function imageUrl(src){return src.startsWith('assets/')?`${src}?v=${encodeURIComponent(D.meta.version)}`:src;}
function logo(slug,cls='team-logo'){const src=D.teams[slug]?.logo||(D.archive.logos[slug]?`https://riftwise.gg/stats/logos/${encodeURIComponent(slug)}.webp`:null);return src?`<img class="${cls}" src="${esc(imageUrl(src))}" alt="${esc(slug)} 队标" loading="lazy" data-fallback="hide">`:'';}
function champ(name){const src=D.champions[name];return src?`<img class="champ-img" src="${esc(imageUrl(src))}" alt="${esc(name)}" loading="lazy">`:`<span class="champ-img" title="${esc(name)}" style="display:inline-grid;place-items:center;color:#8299ad;font-size:10px">${esc(name.slice(0,2))}</span>`;}
function flag(cc){return cc&&/^[a-z]{2}$/i.test(cc)?[...cc.toUpperCase()].map(c=>String.fromCodePoint(c.charCodeAt(0)+127397)).join(''):'';}
function shortTeam(slug,name=''){return D.teams[slug]?.code||D.teams[slug]?.c||({'bilibili-gaming':'BLG',geng:'GEN',t1:'T1','invictus-gaming':'IG','hanwha-life-esports':'HLE','dplus-kia':'DK','top-esports':'TES','g2-esports':'G2','karmine-corp':'KC','team-liquid':'TL','anyones-legend':'AL','ctbc-flying-oyster':'CFO','movistar-koi':'MKOI','team-secret-whales':'TSW',cloud9:'C9',lyon:'LYON',furia:'FUR',los:'LOS','mvk-esports':'MVK'})[slug]||name.slice(0,12);}
function teamSlug(name){return TEAMINDEX.find(t=>t.n===name)?.u||slugify(name);}
function roleTag(role){return `<span class="role">${SHORT[role]||esc(role||'—')}</span>`;}
const stageName=s=>({'Finals':'决赛','Semifinals':'半决赛','Quarterfinals':'四分之一决赛','Round 1':'第一轮','Round 2':'第二轮','Round 3':'第三轮','Round 4':'第四轮','Round 5':'第五轮'})[s]||s;
async function remote(path){
  if(remoteCache.has(path))return remoteCache.get(path);
  const promise=fetch(`${D.meta.sourceSnapshot}/hub/${path}.json`,{signal:AbortSignal.timeout(25000)}).then(r=>{if(!r.ok)throw Error(`数据源暂不可用 (${r.status})`);return r.json();}).catch(e=>{remoteCache.delete(path);throw e;});
  remoteCache.set(path,promise);return promise;
}
async function profile(slug){if(D.profiles[slug])return D.profiles[slug];let p;try{p=await remote('player/'+slug);}catch(e){if(!slug.includes('-'))throw e;p=await remote('player/'+slug.replaceAll('-',''));}D.profiles[slug]=p;return p;}
async function history(slug){if(logs.has(slug))return logs.get(slug);const promise=(async()=>{if(D.profiles[slug]?.photo){try{const r=await fetch(`history/${encodeURIComponent(slug)}.json?v=${encodeURIComponent(D.meta.version)}`);if(r.ok)return await r.json();}catch{}}return remote('playergames/'+slug);})();logs.set(slug,promise);try{return await promise;}catch(e){logs.delete(slug);throw e;}}
async function event(slug){const cached=Object.values(D.stages).find(e=>e.u===slug);return cached||remote('event/'+slug);}
function eventRows(e){return rankPlayers(e?.players||[]);}
function panel(title,body,extra=''){return `<section class="panel"><div class="panel-title">${title}${extra}</div>${body}</section>`;}
function empty(title,text,action=''){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function title(zh,en,meta=''){return `<div class="page-title"><h1>${zh}<span>${en}</span></h1>${meta?`<p>${meta}</p>`:''}</div>`;}
function regionOf(slug){const r=D.stages.all.rosters.find(t=>t.u===slug)?.r;return REGIONS[r]||({'China':'LPL','Korea':'LCK','EMEA':'LEC','Europe':'LEC','North America':'LCS','Brazil':'CBLOL','Pacific':'LCP','Taiwan':'LCP'})[TEAMINDEX.find(t=>t.u===slug)?.region]||'';}
function nav(){const key=route[0]||'players';return `<header class="topbar"><div class="top-inner"><a href="#/players" class="brand" aria-label="RIFT INDEX 首页"><span class="brand-mark">R</span><div><strong>RIFT<span>INDEX</span></strong><small>LEAGUE OF LEGENDS DATABASE</small></div></a><nav class="top-nav" aria-label="主导航">${[['players','选手'],['teams','战队'],['events','赛事'],['matches','比赛'],['compare','选手对比']].map(([k,n])=>`<a class="${key===k||key===k.slice(0,-1)?'active':''}" href="#/${k}">${n}</a>`).join('')}</nav><div class="top-tools"><span>2011 — ${CURRENT_YEAR}</span><a href="#/saved" title="我的关注" style="color:#b8c8d7">${icon('star')}</a><button data-action="about" aria-label="数据说明">${icon('info')}</button></div></div></header>`;}
function leftbar(){const key=route[0]||'players';return `<aside class="leftbar"><section class="side-section"><div class="side-label">STATISTICS / 数据中心</div><nav class="side-menu">${[['players','选手数据库','players',num(INDEX.length)],['teams','战队数据库','cup',num(TEAMINDEX.length)],['events','赛事档案','chart',num(EVENTINDEX.length)],['matches','比赛中心','chart',''],['compare','选手对比','compare',''],['saved','我的关注','star',state.saved.length||'']].map(([k,n,i,c])=>`<a href="#/${k}" class="${key===k?'active':''}">${icon(i)}${n}<span class="count">${c}</span></a>`).join('')}</nav></section><section class="side-section"><div class="side-label">QUICK ACCESS / 快速入口</div><nav class="side-menu"><a href="#/event/worlds-2026">2026 全球总决赛</a><a href="#/player/faker">Faker 选手档案</a><a href="#/player/uzi">Uzi 选手档案</a><a href="#/events?year=2025">2025 赛事档案</a><a href="#/events?year=2013">2013 赛事档案</a></nav></section><section class="side-section side-event"><small>LEAGUE OF LEGENDS</small><div class="world-mark" style="margin-top:13px">WORLDS<br><span>2026</span></div><hr><small>WORLD CHAMPIONS</small>${logo('bilibili-gaming')}<strong style="font-size:13px">BILIBILI GAMING</strong><p style="font-size:10px;margin-top:5px;color:#a2b8ce">BLG 3 : 1 GEN</p><a href="#/match/worlds-2026-main-event-finals-1">查看决赛数据 →</a></section><div class="source-note"><span class="status-dot"></span>快照：${esc(D.meta.built.slice(0,10))}<br>数据范围：2011 — ${CURRENT_YEAR}<br>世界赛已包含决赛<br><a href="#/about">数据来源与统计口径 ↗</a></div></aside>`;}
function rightbar(){const leaders=eventRows(D.stages.all).sort((a,b)=>b.kda-a.kda).slice(0,5);const finals=Object.entries(D.matches).filter(([id])=>/finals/.test(id)).sort((a,b)=>b[1].date.localeCompare(a[1].date)).slice(0,4);return `<aside class="rightbar"><section class="right-panel"><div class="right-heading">世界赛 KDA 榜 <small style="float:right">2026</small></div>${leaders.map((p,i)=>`<a class="mini-player" href="#/player/${p.u}"><span class="rank">${i+1}</span>${portrait(p.u)}<div><strong>${esc(p.n)}</strong><small>${shortTeam(p.tu,p.t)} · ${SHORT[p.r]}</small></div><span class="value">${num(p.kda,2)}</span></a>`).join('')}<a class="right-link" href="#/event/worlds-2026">查看全部统计 →</a></section><section class="right-panel"><div class="right-heading">2026 世界赛淘汰赛</div>${finals.map(([id,m])=>`<a class="mini-result" href="#/match/${id}"><small>${m.date.slice(0,10)} · ${stageName(m.stage)}</small><span class="result-line"><span>${logo(m.a.u)}${esc(m.a.c)}</span><b>${m.sa} : ${m.sb}</b><span>${esc(m.b.c)} ${logo(m.b.u)}</span></span></a>`).join('')}</section><section class="right-panel"><div class="right-heading">历史数据库</div><div class="small-callout"><b style="font-size:24px;font-family:'Barlow Condensed';color:#58738a">${num(D.archive.meta.statsGames)}</b><br>已收录带逐局统计的比赛<br><br><strong>${num(INDEX.length)}</strong> 位已收录选手<br><strong>${num(TEAMINDEX.length)}</strong> 支历史战队<br><strong>2011—${CURRENT_YEAR}</strong> 赛事资料</div><a class="right-link" href="#/about">了解数据覆盖范围 →</a></section><section class="right-panel"><div class="right-heading">六维图怎么看？</div><div class="small-callout">对线 · 输出 · 发育<br>参团 · 视野 · 生存<br><br>同赛事、同位置选手的百分位。虚线代表同位置中位水平，不是官方能力评分。</div></section></aside>`;}
function updateTime(value){return value?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Hong_Kong',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)):'—';}
function updateBar(){const stale=UPDATE&&Date.now()-Date.parse(UPDATE.checkedAt)>48*3600000;return `<div class="freshness-bar ${stale?'delayed':''}"><span class="status-dot"></span><strong>${stale?'更新延迟':'每日自动更新'}</strong><span>数据源 ${updateTime(D.meta.built)}</span><span>最近核验 ${updateTime(UPDATE?.checkedAt)}</span><small>北京时间 · 每天 08:17</small><button data-action="check-update">检查更新 ↻</button></div>`;}
async function checkForUpdate(manual=false){if(updateChecking||document.hidden||(!manual&&Date.now()-lastUpdateCheck<60000))return;updateChecking=true;lastUpdateCheck=Date.now();try{const next=await fetchUpdateManifest();if(UPDATE&&revisionChanged(UPDATE,next)){location.reload();return;}UPDATE=next;const bar=document.querySelector('.freshness-bar');if(bar)bar.outerHTML=updateBar();if(manual)toast('当前已是本站最新发布版本');}catch(error){if(manual)toast('暂时无法检查更新，请稍后重试');}finally{updateChecking=false;}}
function shell(content){app.innerHTML=`${nav()}${updateBar()}<div class="layout">${leftbar()}<main id="main">${content}<footer class="site-footer"><span>RIFT INDEX © ${CURRENT_YEAR} · 独立英雄联盟数据站</span><a href="#/about">RiftWise / Leaguepedia / Oracle’s Elixir</a></footer></main>${rightbar()}</div>${tray()}`;}
function tray(){return state.compare.length?`<div class="compare-tray"><span>${icon('compare')} 对比</span>${state.compare.map(s=>`<span class="chip">${esc(D.profiles[s]?.name||INDEX.find(p=>p.u===s)?.n||s)}<button data-action="compare-remove" data-id="${esc(s)}" aria-label="移除 ${esc(s)}">×</button></span>`).join('')}<a href="#/compare" class="btn primary small">开始对比 →</a></div>`:'';}
function eventBanner(){return `<a href="#/match/worlds-2026-main-event-finals-1" class="headline-event"><div class="event-name"><small>WORLDS 2026 · GRAND FINAL</small><h2>2026 全球总决赛 · 决赛已收录</h2><small>2026.11.14 · New York · 完整逐局统计</small></div><div class="event-score">${logo('bilibili-gaming')}BLG<span class="score-box">3 : 1</span>GEN${logo('geng')}</div></a>`;}
function featured(){return `<div class="featured">${[['knight','世界赛 KDA 第一','9.15','2026 WORLDS'],['faker','职业生涯档案',num(D.profiles.faker?.g)+' 场','CAREER STATISTICS'],['ruler','世界赛场均击杀','5.73','2026 WORLDS']].map(([s,sub,v,k])=>`<a class="featured-card" href="#/player/${s}"><small>${k}</small><strong>${esc(D.profiles[s]?.name||s)}</strong><span class="value">${v}</span><span class="metric">${sub}</span>${portrait(s,'portrait')}</a>`).join('')}</div>`;}
function playerListRows(){if(state.scope==='all'&&!['n','t','r','g','year'].includes(state.sort))state.sort='g';let rows;if(state.scope==='worlds'){rows=eventRows(D.stages.all);}else rows=INDEX.map(p=>{const x=D.profiles[p.u];return {...p,kda:x?.kda,dpm:x?.dpm,csm:x?.csm,winrate:x?x.w/x.g:null};});if(route[0]==='saved')rows=rows.filter(p=>state.saved.includes(p.u));const q=state.q.trim().toLowerCase();rows=rows.filter(p=>(!q||[p.n,p.t,p.real,D.profiles[p.u]?.bio?.native].some(s=>s?.toLowerCase().includes(q)))&&(!state.role||p.r===state.role)&&(!state.region||regionOf(p.tu||teamSlug(p.t))===state.region));rows.sort((a,b)=>{let x=a[state.sort],y=b[state.sort];if(x==null)return 1;if(y==null)return-1;return(state.asc?1:-1)*(typeof x==='string'?x.localeCompare(y):x-y)||b.g-a.g;});return rows;}
function playerTable(rows,scope='worlds'){const headers=[['n','选手'],['t','战队'],['r','位置'],['g','小局'],['kda','KDA'],['dpm','DPM'],[scope==='worlds'?'kp':'year',scope==='worlds'?'参团率':'最近赛季'],['winrate','胜率']];return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(([k,n])=>`<th><button data-action="sort" data-key="${k}" ${scope==='all'&&['kda','dpm','winrate'].includes(k)?'disabled title="历史统计按需载入；全库排序请使用出场小局或名称"':''} class="${state.sort===k?'active':''}">${n}${state.sort===k?(state.asc?' ↑':' ↓'):''}</button></th>`).join('')}<th>对比</th></tr></thead><tbody>${rows.map(p=>{const x=D.profiles[p.u],tu=p.tu||teamSlug(p.t);return `<tr><td><a class="player-cell" href="#/player/${encodeURIComponent(p.u)}">${portrait(p.u)}<span><strong><span class="flag">${flag(x?.bio?.cc)}</span>${esc(p.n)}</strong><small>${esc(x?.bio?.native||x?.bio?.real||p.real||'职业选手')}</small></span></a></td><td><a class="team-cell" href="#/team/${esc(tu)}">${logo(tu)}${esc(shortTeam(tu,p.t))}</a></td><td>${roleTag(p.r)}</td><td>${num(p.g)}</td><td><span class="rating ${p.kda<2?'low':''}">${num(p.kda,2)}</span></td><td>${num(p.dpm)}</td><td>${scope==='worlds'?pct(p.kp):esc(p.year)}</td><td class="${p.winrate>=.5?'positive':''}">${pct(p.winrate)}</td><td><button class="icon-btn ${state.compare.includes(p.u)?'selected':''}" data-action="compare-add" data-id="${esc(p.u)}" aria-label="对比 ${esc(p.n)}">${state.compare.includes(p.u)?'✓':'+'}</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function listContent(){const rows=playerListRows(),max=Math.max(1,Math.ceil(rows.length/15));state.page=Math.min(state.page,max);const page=rows.slice((state.page-1)*15,state.page*15);return {html:`${page.length?playerTable(page,state.scope):empty('没有找到匹配的选手','试试选手 ID、真实姓名或战队名称。','<button class="btn" data-action="reset">清除筛选</button>')}<div class="table-footer"><span>共 ${num(rows.length)} 位选手 · ${state.scope==='worlds'?'2026 世界赛统计':'生涯统计 / 历史战队'}</span><div class="pager"><button class="btn" data-action="page-prev" ${state.page===1?'disabled':''}>‹</button><span style="padding:4px">${state.page} / ${max}</span><button class="btn" data-action="page-next" ${state.page===max?'disabled':''}>›</button></div></div>`,page};}
async function playersPage(){const saved=route[0]==='saved';const result=listContent();shell(`<div class="crumbs">数据中心 / ${saved?'我的关注':'职业选手'}</div>${title(saved?'我的关注':'选手数据','PLAYER STATISTICS',`索引覆盖 2011—${CURRENT_YEAR}`)}${!saved?eventBanner()+featured():''}<div class="tabs"><button data-action="scope" data-scope="all" class="${state.scope==='all'?'active':''}">全部历史 · ${num(INDEX.length)} 位</button><button data-action="scope" data-scope="worlds" class="${state.scope==='worlds'?'active':''}">2026 世界赛 · ${D.meta.players} 位</button></div><div class="search-row"><div class="search-box">${icon('search')}<input id="player-search" placeholder="搜索选手、真实姓名或战队…" aria-label="搜索选手" value="${esc(state.q)}"><kbd>/</kbd></div><button class="btn" data-action="export-list">${icon('download')} CSV</button></div><section class="panel"><div class="filters"><label class="filter"><span>位置</span><select id="role-filter"><option value="">全部位置</option>${Object.entries(ROLES).map(([k,n])=>`<option value="${k}" ${state.role===k?'selected':''}>${n} / ${SHORT[k]}</option>`).join('')}</select></label><label class="filter"><span>赛区 / 已知归属</span><select id="region-filter"><option value="">全部赛区</option>${['LCK','LPL','LEC','LCS','LCP','CBLOL'].map(r=>`<option ${state.region===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="filter"><span>排序</span><select id="sort-filter">${(state.scope==='all'?[['g','出场小局'],['year','最近赛季'],['n','选手名称']]:[['g','出场小局'],['kda','KDA'],['dpm','分均伤害'],['winrate','胜率'],['n','选手名称']]).map(([v,t])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn small" style="align-self:end" data-action="reset">重置</button></div><div id="list-results">${result.html}</div></section><p class="hint">KDA =（击杀 + 助攻）/ 死亡；DPM = 每分钟对英雄伤害。点击头像或选手 ID 查看完整档案。历史缺失字段显示「—」。${state.scope==='all'?'历史统计按需载入，全库支持小局、名称及年份排序；完整指标排名请切换到指定赛事。':''}</p>`);warmProfiles(result.page);}
async function warmProfiles(rows){const token=revision;const missing=rows.filter(p=>!D.profiles[p.u]);if(!missing.length)return;await Promise.allSettled(missing.map(p=>profile(p.u)));if(token===revision&&$('#list-results'))$('#list-results').innerHTML=listContent().html;}
function updateList(){const r=listContent();$('#list-results').innerHTML=r.html;warmProfiles(r.page);}
function radar(p,other=null){const values=p?.radar||Array(6).fill(null),center=[160,143],radius=91;const point=(i,value=100)=>{const a=(i*60-90)*Math.PI/180;return[center[0]+Math.cos(a)*radius*value/100,center[1]+Math.sin(a)*radius*value/100];};const points=(v)=>v.map((n,i)=>point(i,n??0).join(',')).join(' ');return `<div class="radar-wrap"><svg class="radar" viewBox="0 0 320 285" role="img" aria-label="六维能力雷达图：${DIMENSIONS.map((d,i)=>d.name+' '+num(values[i],0)).join('，')}"><title>同赛事同位置百分位，0—100</title>${[20,40,60,80,100].map(v=>`<polygon class="grid" points="${points(Array(6).fill(v))}"/>`).join('')}${DIMENSIONS.map((d,i)=>`<line class="axis" x1="160" y1="143" x2="${point(i)[0]}" y2="${point(i)[1]}"/>`).join('')}<polygon class="baseline" points="${points(Array(6).fill(50))}"/>${values.every(Number.isFinite)?`<polygon class="area" points="${points(values)}"/>${values.map((v,i)=>`<circle class="point" cx="${point(i,v)[0]}" cy="${point(i,v)[1]}" r="3"><title>${DIMENSIONS[i].name}: ${num(v)} 百分位</title></circle>`).join('')}`:`<text x="160" y="140" text-anchor="middle">数据不足，不生成完整六维图</text>`}${other?.radar?.every(Number.isFinite)?`<polygon class="compare" points="${points(other.radar)}"/>`:''}${DIMENSIONS.map((d,i)=>{let xy=point(i,133);return `<text x="${xy[0]}" y="${xy[1]-1}" text-anchor="middle">${d.name}<tspan x="${xy[0]}" dy="14" style="font-size:11px;fill:#3c799f;font-weight:700">${num(values[i])}</tspan></text>`;}).join('')}</svg><div class="legend"><span><i></i>${esc(p?.n||'选手')}</span><span><i class="${other?'orange':'dashed'}"></i>${other?esc(other.n):'同位置中位线'}</span></div><p class="radar-note">同位置 ≥3 小局选手，${p?.peers||0} 人样本 · <a href="#/about">评分口径</a></p></div>`;}
function statsStrip(p,career=false){const cells=career?[['生涯小局',num(p.g)],['生涯胜率',pct(p.w/p.g)],['生涯 KDA',num(p.kda,2)],['分均伤害',num(p.dpm)],['分均补刀',num(p.csm,1)],['英雄池',num(p.nChamps)]]:[['出场小局',num(p?.g)],['胜率',pct(p?.winrate)],['KDA',num(p?.kda,2)],['分均伤害',num(p?.dpm)],['分均补刀',num(p?.csm,1)],['参团率',pct(p?.kp)]];return `<div class="stats-strip">${cells.map(([k,v],i)=>`<div class="stat ${i===2?'highlight':''}"><b>${v}</b><small>${k}</small></div>`).join('')}</div>`;}
function normalGames(rows){return rows.map(r=>({date:r[0],id:r[1],c:r[2],k:r[3],d:r[4],a:r[5],win:!!r[6],team:{n:r[7]},opp:{n:r[8]},event:r[9],role:r[10],eventSlug:r[11],cs:r[12],gd:r[13],dm:r[14],v:r[15],minutes:r[16],number:r[22],patch:r[24],kda:(r[3]+r[5])/Math.max(1,r[4])})).sort((a,b)=>b.date.localeCompare(a.date)||(b.number||0)-(a.number||0));}
function champTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>英雄</th><th>小局</th><th>胜率</th><th>KDA</th><th>K / D / A</th></tr></thead><tbody>${rows.map(c=>`<tr><td><div class="champ-cell">${champ(c.c)}<div><strong>${esc(c.c)}</strong><div class="champ-bar"><i style="width:${c.w/c.g*100}%"></i></div></div></div></td><td>${c.g}</td><td class="${c.w/c.g>=.5?'positive':''}">${pct(c.w/c.g)}</td><td><b>${num(c.kda,2)}</b></td><td>${num(c.k/c.g,1)} / ${num(c.d/c.g,1)} / ${num(c.a/c.g,1)}</td></tr>`).join('')}</tbody></table></div>`;}
function gamesTable(games,limit=20){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>日期 / 赛事</th><th>对手</th><th>英雄</th><th>K / D / A</th><th>结果</th><th></th></tr></thead><tbody>${games.slice(0,limit).map(g=>`<tr><td style="font-size:10px">${esc(g.date.slice(0,10))}<br><small>${esc(g.event||stageName(g.stage))} · G${g.number||'?'}</small></td><td style="font-size:10px">${esc(g.opp.n)}</td><td title="${esc(g.c)}">${champ(g.c)}</td><td>${g.k} / ${g.d} / ${g.a}</td><td><span class="${g.win?'win-label':'loss-label'}">${g.win?'WIN':'LOSS'}</span></td><td><a href="#/match/${esc(g.id)}" class="btn small">详情</a></td></tr>`).join('')}</tbody></table></div>`;}
function formChart(games){const recent=games.slice(0,12).reverse(),max=Math.max(10,...recent.map(g=>g.kda)),coords=recent.map((g,i)=>[15+i*(270/Math.max(1,recent.length-1)),85-g.kda/max*65]);return `<div class="panel-body"><div class="form">${games.slice(0,10).reverse().map(g=>`<i class="${g.win?'':'loss'}" title="${esc(g.date)} ${g.k}/${g.d}/${g.a}">${g.win?'W':'L'}</i>`).join('')}</div><svg class="form-chart" viewBox="0 0 300 100" role="img" aria-label="最近十二局 KDA 走势"><path d="M15 20H285M15 50H285M15 85H285" stroke="#dce5ed" fill="none" stroke-dasharray="3 3"/><polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#4b8ab6" stroke-width="2"/>${coords.map((c,i)=>`<circle cx="${c[0]}" cy="${c[1]}" r="3" fill="#76a4c5"><title>KDA ${num(recent[i].kda,2)}</title></circle>`).join('')}</svg><small>较早 ← 最近 ${recent.length} 场 KDA → 较新</small></div>`;}
async function playerPage(slug){const token=revision;shell(`${title('选手档案','PLAYER PROFILE')}<div class="loading">正在载入完整职业档案…</div>`);const p=await profile(slug);if(token!==revision)return;currentProfile=p;if(state.detailSlug!==slug){state.detailSlug=slug;state.detailEvent=p.events?.find(e=>e.g>0)?.e||'';state.tab='overview';state.historyYear='all';}let gameError='';const [evResult,logResult]=await Promise.allSettled([state.detailEvent?event(state.detailEvent):Promise.resolve(null),history(slug)]);if(token!==revision)return;currentEvent=evResult.status==='fulfilled'?evResult.value:null;const row=currentEvent?eventRows(currentEvent).find(r=>r.u===p.u||r.u===slug):null;let games=logResult.status==='fulfilled'?normalGames(logResult.value):[];if(logResult.status==='rejected')gameError='历史逐局数据暂时无法加载，可稍后重试。';const selectedGames=games.filter(g=>g.eventSlug===state.detailEvent),filteredGames=games.filter(g=>state.historyYear==='all'||g.date.startsWith(state.historyYear));const eventOptions=(p.events||[]).filter(e=>e.g>0).map(e=>`<option value="${esc(e.e)}" ${state.detailEvent===e.e?'selected':''}>${esc(e.en)} · ${e.g} 局</option>`).join('');let content='';
  if(state.tab==='overview')content=`<div class="panel"><div class="filters"><label class="filter"><span>赛事统计范围 · 六维图与下方数值使用同一范围</span><select id="detail-event">${eventOptions}</select></label><button class="btn small" style="align-self:end" data-action="method">统计口径</button></div></div>${row?statsStrip(row)+`<div class="two-col">${panel('选手六维能力',radar(row),'<small>同位置百分位 / 100</small>')}${panel('详细数据',`<div>${[['15 分钟经济差',sign(row.gd15)],['15 分钟补刀差',sign(row.cs15)],['15 分钟经验差',sign(row.xp15)],['分均经济',num(row.gpm)],['伤害占比',pct(row.damageShare)],['经济占比',pct(row.goldShare)],['分均视野得分',num(row.vpm,2)],['场均死亡',num(row.d/row.g,2)]].map(([k,v])=>`<div class="stat-row"><span>${k}</span><b>${v}</b></div>`).join('')}</div>`)}</div><div class="two-col">${panel('本赛事常用英雄',selectedGames.length?champTable(championStats(selectedGames).slice(0,5)):empty('逐局数据尚未载入','可在英雄池页查看生涯英雄统计。'))}${panel('近期表现',formChart(selectedGames.length?selectedGames:games),`<small>${selectedGames.length?'当前赛事':'职业生涯最近比赛'}</small>`)}</div>${panel('最近比赛',gamesTable(selectedGames.length?selectedGames:games,8),'<button class="btn small" data-action="tab" data-tab="matches">全部比赛 →</button>')}`:`<div class="notice">${currentEvent?'该赛事缺少可计算的选手详细统计。':'赛事数据暂未载入。'}不生成无法核验的六维分数。<button class="btn small" data-action="retry">重试</button></div>${panel('生涯常用英雄',champTable(p.champs.slice(0,8)))}${panel('最近比赛',gamesTable(games,8))}`}`;
  else if(state.tab==='champions')content=`${yearFilter(p)}<div class="notice">${state.historyYear==='all'?'职业生涯全部已收录对局':state.historyYear+' 赛季'} · ${filteredGames.length} 小局 · ${championStats(filteredGames).length} 个英雄</div>${panel('英雄池统计',champTable(championStats(filteredGames)))}`;
  else if(state.tab==='matches')content=`${yearFilter(p)}<div class="search-row"><p class="muted" style="flex:1;padding:10px 0">${state.historyYear==='all'?'职业生涯':state.historyYear} · 共 ${num(filteredGames.length)} 小局</p><button class="btn" data-action="export-history">${icon('download')} 导出当前年份</button></div>${gameError?`<div class="notice">${gameError}<button class="btn" data-action="retry">重试</button></div>`:''}${panel('逐场比赛记录',gamesTable(filteredGames,100))}${filteredGames.length>100?'<p class="hint">页面显示最近 100 局；CSV 导出包含当前年份筛选下的全部记录。</p>':''}`;
  else content=`${statsStrip(p,true)}<div class="two-col">${panel('历年表现',`<table class="data-table"><thead><tr><th>赛季 / 战队</th><th>小局</th><th>胜率</th><th>KDA</th></tr></thead><tbody>${p.years.map(y=>`<tr><td><strong>${y.y}</strong><br><small>${esc(y.team)}</small></td><td>${y.g}</td><td>${pct(y.w/y.g)}</td><td>${num(y.kda,2)}</td></tr>`).join('')}</tbody></table>`)}<div>${panel('战队履历',`<div class="timeline">${p.teams.map(t=>`<div class="timeline-item"><a href="#/team/${esc(t.u)}"><strong>${esc(t.n)}</strong></a><small>${t.from} — ${t.to} · ${t.g} 小局</small></div>`).join('')}</div>`)}${panel('冠军荣誉',p.titles?.length?`<div class="timeline">${p.titles.map(t=>`<div class="timeline-item"><a href="#/event/${esc(t.e)}">${icon('cup')} ${esc(t.t)}</a><small>${t.date} · ${esc(t.kind)}</small></div>`).join('')}</div>`:empty('暂无已收录冠军','以来源赛事档案为准。'))}</div></div>`;
  const age=p.bio?.born?Math.floor((new Date()-new Date(p.bio.born))/31557600000):null;shell(`<div class="crumbs"><a href="#/players">选手数据库</a> / ${esc(p.name)}</div><div class="player-banner">${portrait(slug,'big-portrait')}<div class="player-info"><h1>${esc(p.name)}</h1><p class="real-name">${flag(p.bio?.cc)} ${esc(p.bio?.real||'')} ${esc(p.bio?.native||'')}</p><div class="info-lines"><span>最近所属战队</span><b><a href="#/team/${esc(p.clubU)}">${logo(p.clubU)}${esc(p.club)}</a></b><span>位置 / 地区</span><b>${ROLES[p.role]||esc(p.role)} · ${esc(p.bio?.country||'未收录')}</b><span>已收录记录</span><b>${p.years?.at(-1)?.y||'—'} — ${p.years?.[0]?.y||'—'}${age?' · '+age+' 岁':''}</b></div></div><div class="banner-actions"><button class="btn small" data-action="favorite" data-id="${esc(slug)}">${icon('star')}${state.saved.includes(slug)?'已关注':'关注'}</button><button class="btn primary small" data-action="compare-add" data-id="${esc(slug)}">加入对比</button></div><div class="banner-watermark">${esc(p.name.toUpperCase())}</div></div><div class="tabs">${[['overview','数据总览'],['champions','英雄池'],['matches','比赛记录'],['career','职业生涯']].map(([k,n])=>`<button data-action="tab" data-tab="${k}" class="${state.tab===k?'active':''}">${n}</button>`).join('')}</div>${content}<p class="hint">最近战队按最后一条已收录比赛显示，不能视为实时转会确认。<a href="https://riftwise.gg/player/${encodeURIComponent(p.u)}" target="_blank" rel="noopener">核对原始档案 ↗</a></p>`);
}
function yearFilter(p){return `<div class="year-chips"><button data-action="history-year" data-year="all" class="${state.historyYear==='all'?'active':''}">全部生涯</button>${p.years.map(y=>`<button data-action="history-year" data-year="${y.y}" class="${state.historyYear===y.y?'active':''}">${y.y}</button>`).join('')}</div>`;}
async function eventsPage(){const year=state.year;const q=state.eventsQ.toLowerCase();const filtered=EVENTINDEX.filter(e=>(year==='all'||e.year===year)&&(!q||[e.n,e.league].some(s=>s.toLowerCase().includes(q)))).sort((a,b)=>b.date.localeCompare(a.date)||b.g-a.g);const max=Math.max(1,Math.ceil(filtered.length/40));state.eventPage=Math.min(state.eventPage,max);shell(`${title('赛事档案','EVENT ARCHIVE',`${num(EVENTINDEX.length)} 项历史赛事`)}<div class="panel"><div class="filters"><label class="filter"><span>年份</span><select id="event-year"><option value="all">全部年份</option>${D.archive.meta.years.filter(y=>+y<=CURRENT_YEAR).map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label class="filter" style="flex:3"><span>查找赛事或联赛</span><input id="event-search" placeholder="例如 Worlds、LCK、LPL、MSI…" value="${esc(state.eventsQ)}"></label></div><div class="event-list">${filtered.slice((state.eventPage-1)*40,state.eventPage*40).map(e=>`<a href="#/event/${esc(e.u)}"><span><strong>${esc(e.n)}</strong><small>${esc(e.league)} · ${esc(e.date||e.year)}</small></span><span class="tag">${e.g} 小局 →</span></a>`).join('')||empty('没有匹配的赛事','更换年份或搜索词。')}</div><div class="table-footer"><span>${num(filtered.length)} 项赛事</span><div class="pager"><button class="btn" data-action="event-prev" ${state.eventPage===1?'disabled':''}>‹</button><span>${state.eventPage}/${max}</span><button class="btn" data-action="event-next" ${state.eventPage===max?'disabled':''}>›</button></div></div></div>`);}
async function eventPage(slug){const token=revision;shell(title('赛事数据','EVENT STATISTICS')+'<div class="loading">正在载入赛事档案…</div>');const e=await event(slug);if(token!==revision)return;const rows=eventRows(e).sort((a,b)=>{const x=a[state.sort],y=b[state.sort];if(x==null)return 1;if(y==null)return -1;return (state.asc?1:-1)*(typeof x==='string'?x.localeCompare(y):x-y);});shell(`<div class="crumbs"><a href="#/events">赛事档案</a> / ${esc(e.n)}</div>${title(esc(e.n),'EVENT STATISTICS',`${e.start||'—'} — ${e.end||'—'}`)}<div class="stats-strip">${[['小局',e.games||e.statsGames],['参赛选手',e.players?.length],['战队',e.teams?.length],['年份',e.year],['赛区',e.region],['赛事类型',e.type||'—']].map(([k,v])=>`<div class="stat"><b style="font-size:${typeof v==='string'&&v.length>5?'16':'27'}px">${esc(v??'—')}</b><small>${k}</small></div>`).join('')}</div>${e.children?.length?`<div class="year-chips">${e.children.map(c=>`<a class="btn small" href="#/event/${esc(c.u)}">${esc(c.n)}</a>`).join('')}</div>`:''}<div class="two-col">${panel('最终排名',`<div>${(e.results||[]).slice(0,12).map(r=>`<a class="stat-row" href="#/team/${esc(r.u)}"><span>#${esc(r.p)}</span><b>${logo(r.u)}${esc(r.t)}</b></a>`).join('')||empty('暂无排名记录','来源未提供此阶段排名。')}</div>`)}${panel('赛事信息',`<div class="panel-body"><p style="margin-bottom:12px">${esc(e.league||'League of Legends')} · ${esc(e.country||e.region||'')}</p><p class="muted">选手榜可点击列名排序；点击选手可查看跨赛季职业档案，并在档案中切换到本赛事查看六维图。</p><div style="margin-top:15px"><a class="btn" href="#/matches?year=${esc(e.year)}&event=${esc(e.u)}">查看比赛与赛程 →</a> <a class="btn" href="https://riftwise.gg/tournament/${encodeURIComponent(e.u)}" target="_blank" rel="noopener">原始赛事来源 ↗</a></div></div>`)}</div>${panel('选手统计 · 本赛事',rows.length?playerTable(rows,'worlds'):empty('暂无逐局选手统计','早期赛事可能只有赛果或阵容。'))}`);warmProfilesForPage(rows,token);}
async function warmProfilesForPage(rows,token){await Promise.allSettled(rows.slice(0,15).filter(p=>!D.profiles[p.u]).map(p=>profile(p.u)));/* Rows remain readable even if portrait metadata is unavailable. */}
async function teamsPage(){const q=state.teamQ.toLowerCase();const teams=TEAMINDEX.filter(t=>!q||[t.n,t.alias,t.code].some(s=>s.toLowerCase().includes(q))).slice(0,100);shell(`${title('战队数据库','TEAM DATABASE',`${num(TEAMINDEX.length)} 支历史战队`)}<div class="search-row"><div class="search-box">${icon('search')}<input id="team-search" placeholder="搜索当前或历史战队名称…" value="${esc(state.teamQ)}"></div></div><div class="panel"><div class="event-list">${teams.map(t=>`<a href="#/team/${esc(t.u)}"><span style="display:flex;align-items:center;gap:10px">${logo(t.u)}<span><strong>${esc(t.n)}</strong><small>${esc(t.region)} · 最近赛季 ${esc(t.year)}</small></span></span><span>${num(t.g)} 小局 →</span></a>`).join('')}</div></div><p class="hint">按历史出场小局排序，显示前 100 项匹配；可搜索完整数据库。</p>`);}
async function teamPage(slug){const token=revision;shell(title('战队档案','TEAM PROFILE')+'<div class="loading">正在载入战队历史…</div>');const t=await remote('team/'+slug);if(token!==revision)return;const roster=D.stages.all.rosters.find(x=>x.u===slug);const players=roster?.p?.filter(p=>ROLES[p[2]])||[];shell(`<div class="crumbs"><a href="#/teams">战队数据库</a> / ${esc(t.name||t.n)}</div>${title(esc(t.name||t.n||slug),'TEAM PROFILE')}<div class="panel"><div class="panel-body" style="display:flex;gap:20px;align-items:center">${logo(slug)}<div><h2>${esc(t.name||t.n||slug)}</h2><p class="muted">${esc(t.region||t.country||'')} · ${num(t.g)} 已收录小局 · ${pct(t.g?t.w/t.g:null)} 胜率</p></div></div></div>${players.length?panel('2026 世界赛阵容',`<div class="panel-body roster">${players.map(([n,u,r])=>`<a href="#/player/${u}">${portrait(u)}<strong>${esc(n)}</strong><span>${ROLES[r]}</span></a>`).join('')}</div>`):''}${panel('历年记录',`<div class="event-list">${(t.years||[]).map(y=>`<a href="#/events?year=${y.y}"><strong>${esc(y.y)}</strong><span>${num(y.g)} 小局 · ${pct(y.g?y.w/y.g:null)}</span></a>`).join('')||'<div class="panel-body muted">该战队暂无年度汇总。</div>'}</div>`)}${panel('赛事记录',`<div class="event-list">${(t.events||[]).slice(0,80).map(e=>`<a href="#/event/${esc(e.e||e.u)}"><span>${esc(e.en||e.n)}<small>${esc(e.date||'')}</small></span><span>${num(e.g)} 小局</span></a>`).join('')}</div>`)}<a class="btn" target="_blank" rel="noopener" href="https://riftwise.gg/team/${encodeURIComponent(slug)}">原始战队档案 ↗</a>`);}
let matchCatalog;
const MATCH_LABELS={completed:'已结束',unstarted:'待开赛',inProgress:'进行中 · 快照',unconfirmed:'状态待确认',canceled:'已取消'};
const matchDate=(row,onlyDay=false)=>!row.date?'日期待定':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit',...(!onlyDay&&row.precision==='minute'?{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}:{})}).format(new Date(row.date));
function sourceMatchDate(raw){if(!raw)return '日期待定';const value=raw.trim().replace(' ','T'),iso=/T/.test(value)&&!/(Z|[+-]\d{2}:?\d{2})$/.test(value)?value+'Z':value;if(!Number.isFinite(Date.parse(iso)))return '日期待定';return matchDate({date:iso,precision:raw.length>10?'minute':'day'})+'（北京时间 / 香港时间）';}
function matchHref(patch={}){const f={...state.match,...patch},q=new URLSearchParams();for(const [k,v]of Object.entries(f))if(v!==''&&v!=null)q.set(k,v);return '#/matches?'+q;}
function changeMatchFilters(patch){Object.assign(state.match,{page:1},patch);historyReplaceHash(matchHref());return render();}
async function matchData(){const index=await matchFile('match-index.json',UPDATE.matchIndexSha256);const schedule=await matchFile(index.schedule.file,index.schedule.sha256);matchCatalog={index,schedule};return matchCatalog;}
function matchTeam(t){const badge=t.image?`<img class="team-logo" src="${esc(t.image)}" alt="${esc(t.n)} 队标" loading="lazy" data-fallback="hide">`:logo(t.u)||`<span class="team-initials" aria-hidden="true">${esc((t.c||t.n||'?').slice(0,3))}</span>`;return `<span class="match-team">${badge}<span>${esc(t.n)}<small>${esc(t.c||'')}</small></span></span>`;}
function matchRow(row,asOf){const status=matchStatus(row,asOf),href=row.slug?'#/match/'+encodeURIComponent(row.slug):'#/fixture/'+encodeURIComponent(row.id),scored=['completed','inProgress'].includes(status);return `<a class="match-row" href="${href}"><div class="match-when"><strong>${row.precision==='minute'?matchDate(row).split(' ').at(-1):'时间待定'}</strong><small>BO${row.bo||'?'}</small></div><div class="match-pair">${matchTeam(row.a)}<div class="match-score ${status}"><strong>${scored?`${num(row.sa)} : ${num(row.sb)}`:'VS'}</strong><small>${MATCH_LABELS[status]}</small></div>${matchTeam(row.b)}</div><div class="match-event"><span class="tag">${esc(row.league)}</span><strong>${esc(row.eventName)}</strong><small>${esc(stageName(row.stage))} · ${row.slug?'比赛详情 →':'赛程信息 →'}</small></div></a>`;}
async function matchesPage(){const token=revision;shell(title('比赛中心','MATCH CENTER')+'<div class="loading">正在载入跨赛事赛程与结果…</div>');const {index,schedule}=await matchData();if(token!==revision)return;const f=state.match;const shards=Object.entries(index.years).filter(([y])=>f.year==='all'||y===f.year);const archive=(await Promise.all(shards.map(([,v])=>matchFile(v.file,v.sha256)))).flat();if(token!==revision)return;
const rows=mergeMatches(archive,schedule.matches.filter(r=>f.year==='all'||r.year===f.year));
const eventMap=new Map(index.events.map(e=>[e.u,e]));for(const row of schedule.matches)if(!eventMap.has(row.event))eventMap.set(row.event,{u:row.event,n:row.eventName,league:row.league,years:[row.year]});
const events=[...eventMap.values()].filter(e=>(f.year==='all'||e.years.includes(f.year))&&(f.league==='all'||e.league===f.league)).sort((a,b)=>b.n.localeCompare(a.n));
const leagues=[...new Set([...index.leagues,...schedule.matches.map(r=>r.league)])].sort((a,b)=>{const order=['LPL','LCK','LEC','MSI','Worlds','First Stand','LCS','LTA','LCP'];return (order.indexOf(a)<0?99:order.indexOf(a))-(order.indexOf(b)<0?99:order.indexOf(b))||a.localeCompare(b);});
const years=[...new Set([...Object.keys(index.years),...schedule.matches.map(r=>r.year)])].sort().reverse();
const filtered=filterMatches(rows,f,schedule.asOf),base=filterMatches(rows,{...f,status:'all'},schedule.asOf),max=Math.max(1,Math.ceil(filtered.length/40));f.page=Math.min(Math.max(1,Number(f.page)||1),max);const page=filtered.slice((f.page-1)*40,f.page*40);
let lastDay='';const listing=page.map(row=>{const day=matchDate(row,true);const heading=day!==lastDay?`<div class="match-day">${esc(day)}<small>北京时间 / 香港时间</small></div>`:'';lastDay=day;return heading+matchRow(row,schedule.asOf);}).join('');
const statuses=[['all','全部比赛'],['completed','比赛结果'],['upcoming','赛程'],['unconfirmed','待确认']];
shell(`${title('比赛中心','MATCHES & RESULTS',`${num(index.archiveCount)} 场历史系列赛 · 每日自动更新`)}<div class="match-intro"><div><strong>LPL · LCK · LEC · MSI · WORLDS</strong><span>跨年份赛果、已公布赛程与完整比赛详情</span></div><small>赛程源更新 ${updateTime(schedule.asOf)}<br>数据源时间与本站核验时间分别显示</small></div><section class="panel"><div class="filters match-filters"><label class="filter"><span>年份</span><select id="match-year"><option value="all" ${f.year==='all'?'selected':''}>全部年份</option>${years.map(y=>`<option value="${y}" ${y===f.year?'selected':''}>${y}</option>`).join('')}</select></label><label class="filter"><span>联赛 / 国际赛事</span><select id="match-league"><option value="all">全部赛事</option>${leagues.map(l=>`<option ${f.league===l?'selected':''}>${esc(l)}</option>`).join('')}</select></label><label class="filter match-event-filter"><span>具体赛事 / 赛段</span><select id="match-event"><option value="all">全部赛段</option>${events.map(e=>`<option value="${esc(e.u)}" ${f.event===e.u?'selected':''}>${esc(e.n)}</option>`).join('')}</select></label><button class="btn small" data-action="match-reset">重置</button></div><div class="match-search"><div class="search-box">${icon('search')}<input id="match-search" aria-label="搜索比赛" placeholder="搜索战队、赛事或阶段，例如 T1、BLG、Playoffs…" value="${esc(f.q)}"></div></div><div class="tabs match-tabs">${statuses.map(([status,label])=>`<button data-action="match-status" data-status="${status}" class="${f.status===status?'active':''}">${label} <small>${filterMatches(base,{status},schedule.asOf).length}</small></button>`).join('')}</div><div class="match-list">${listing||empty(f.status==='upcoming'?'当前筛选暂无待开赛记录':'没有匹配的比赛','只显示数据源已公布的赛程与赛果；可切换年份、赛事或清除搜索。','<button class="btn" data-action="match-reset">重置筛选</button>')}</div><div class="table-footer"><span>${num(filtered.length)} 场匹配 · 第 ${f.page} / ${max} 页</span><div class="pager"><button class="btn" data-action="match-prev" ${f.page<=1?'disabled':''}>上一页</button><button class="btn" data-action="match-next" ${f.page>=max?'disabled':''}>下一页</button></div></div></section><p class="hint">日期统一为北京时间 / 香港时间；未提供精确时间的记录显示「时间待定」。LEC 历史包含 EU LCS，LCK 历史包含早期 Champions。赛程每日同步，进行中状态为来源快照，非实时比分。</p><p class="hint">历史赛果：<a href="https://riftwise.gg/tournaments" target="_blank" rel="noopener">RiftWise / Leaguepedia</a> · 最新赛程：<a href="https://riftwise.gg/schedule" target="_blank" rel="noopener">Riot LoL Esports（经 RiftWise）</a></p>`);}
async function fixturePage(id){const token=revision;shell(title('赛程信息','FIXTURE')+'<div class="loading">正在读取赛程…</div>');const {index,schedule}=await matchData();let row=schedule.matches.find(r=>r.id===id);if(!row){for(const y of Object.values(index.years)){row=(await matchFile(y.file,y.sha256)).find(r=>r.id===id);if(row)break;}}if(token!==revision)return;if(!row)throw Error('该赛程已变更或不在最新公布列表中，请返回比赛中心');const status=matchStatus(row,schedule.asOf);shell(`<div class="crumbs"><a href="${matchHref()}">比赛中心</a> / ${esc(row.league)}</div>${title(`${esc(row.a.n)} vs ${esc(row.b.n)}`,'FIXTURE DETAILS',matchDate(row))}<div class="panel"><div class="panel-title">${esc(row.eventName)}<span>${MATCH_LABELS[status]}</span></div><div class="fixture-teams">${matchTeam(row.a)}<strong>${status==='completed'||status==='inProgress'?`${num(row.sa)} : ${num(row.sb)}`:'VS'}</strong>${matchTeam(row.b)}</div><div class="panel-body"><p>${esc(stageName(row.stage))} · BO${row.bo||'?'} · ${matchDate(row)}（北京时间）</p></div></div><div class="notice">${status==='completed'?'该比赛已公布赛果，逐局技术统计等待数据源归档。':'以数据源最终公布的队伍、时间与比赛状态为准。'}赛程源更新：${esc(schedule.asOf)}。本站每日同步。</div><a class="btn" href="https://riftwise.gg/schedule" target="_blank" rel="noopener">核对官方赛程来源 ↗</a>`);}
async function matchPage(slug){const token=revision;shell(title('比赛详情','MATCH DETAILS')+'<div class="loading">正在载入比赛数据…</div>');const m=D.matches[slug]||await remote('game/'+slug);if(token!==revision)return;shell(`<div class="crumbs"><a href="#/matches">比赛记录</a> / ${esc(m.en)} / ${esc(stageName(m.stage))}</div>${title(`${esc(m.a.n)} vs ${esc(m.b.n)}`,'MATCH DETAILS',esc(sourceMatchDate(m.date)))}<div class="headline-event"><div class="event-name"><h2>${esc(m.en)}</h2><small>${stageName(m.stage)} · BO${m.bo}</small></div><div class="event-score">${logo(m.a.u)}${esc(m.a.c||'')}<span class="score-box">${m.sa} : ${m.sb}</span>${esc(m.b.c||'')}${logo(m.b.u)}</div></div>${(m.games||[]).map(g=>panel(`GAME ${g.n} · ${g.min?num(g.min,1)+' 分钟':'时长未收录'} · ${g.w===1?esc(m.a.n)+' 获胜':g.w===2?esc(m.b.n)+' 获胜':'赛果未录入'}`,`<div class="game-details">${[1,2].map(side=>{const team=side===1?(g.blue==='a'?m.a:m.b):(g.blue==='a'?m.b:m.a);return `<div class="game-side-title">${logo(team.u)}${esc(team.n)} <small>${side===1?'蓝色方':'红色方'}</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>选手</th><th>英雄</th><th>K / D / A</th><th>补刀</th><th>伤害</th><th>经济</th><th>视野</th></tr></thead><tbody>${(g.p||[]).filter(p=>p.s===side).map(p=>`<tr><td><a href="#/player/${esc(p.u)}">${esc(p.n)}</a> ${roleTag(p.r)}</td><td title="${esc(p.c)}">${champ(p.c)}</td><td>${p.k} / ${p.d} / ${p.a}</td><td>${num(p.cs)}</td><td>${num(p.dm)}</td><td>${num(p.gd)}</td><td>${num(p.v)}</td></tr>`).join('')}</tbody></table></div>`;}).join('')}</div>${g.vgs||g.vpb?`<div class="panel-body"><a class="btn small" href="${esc(g.vgs||g.vpb)}" target="_blank" rel="noopener">观看本局录像 ↗</a></div>`:''}`,`<small>版本 ${esc(g.patch||'—')}</small>`)).join('')}`);}
async function comparePage(){const token=revision;if(!state.compare.length)state.compare=['knight','chovy'];const ids=state.compare;const choices=`<div class="compare-inputs">${[0,1].map(i=>`<div><input id="compare-search-${i}" placeholder="搜索${i?'第二':'第一'}位选手…" aria-label="搜索${i?'第二':'第一'}位对比选手"><div id="compare-results-${i}" class="search-results" hidden></div></div>`).join('')}</div>`;shell(title('选手对比','PLAYER COMPARISON')+choices+'<div class="loading">正在准备对比数据…</div>');const ps=await Promise.all(ids.map(profile));if(token!==revision)return;let ev=null;try{ev=await event(state.compareEvent);}catch{}if(token!==revision)return;const all=eventRows(ev),a=all.find(x=>x.u===ids[0]),b=all.find(x=>x.u===ids[1]);let shared=[];if(ps.length===2){const bs=new Set(ps[1].events?.map(e=>e.e));shared=(ps[0].events||[]).filter(e=>bs.has(e.e));}const comparison=ps.length===2?`<div class="compare-head">${ps.map((p,i)=>`${i?'<div class="compare-vs">VS</div>':''}<a class="compare-player" href="#/player/${ids[i]}">${portrait(ids[i],'portrait')}<h2>${esc(p.name)}</h2><p>${esc(p.club)} · ${ROLES[p.role]||p.role}</p></a>`).join('')}</div><div class="panel"><div class="filters"><label class="filter"><span>选择共同赛事</span><select id="compare-event"><option value="worlds-2026" ${state.compareEvent==='worlds-2026'?'selected':''}>2026 全球总决赛 · 全部阶段</option>${shared.map(e=>`<option value="${e.e}" ${state.compareEvent===e.e?'selected':''}>${esc(e.en)}</option>`).join('')}</select></label></div></div>${a&&b?`${a.r!==b.r?'<div class="notice">两位选手位置不同：雷达图分别对各自位置归一化，不能视为绝对实力比较。</div>':''}<div class="two-col">${panel('六维能力对比',radar(a,b))}${panel('核心数据对比',`<table class="compare-table"><tbody>${[['KDA','kda',2],['胜率','winrate',1],['分均伤害','dpm',0],['分均补刀','csm',1],['参团率','kp',1],['15 分钟经济差','gd15',0],['分均视野','vpm',2],['出场小局','g',0]].map(([n,k,d])=>`<tr><td class="${a[k]!=null&&b[k]!=null&&a[k]>b[k]?'better':''}">${['kp','winrate'].includes(k)?pct(a[k]):num(a[k],d)}</td><td>${n}</td><td class="${a[k]!=null&&b[k]!=null&&b[k]>a[k]?'better':''}">${['kp','winrate'].includes(k)?pct(b[k]):num(b[k],d)}</td></tr>`).join('')}</tbody></table>`)}</div>`:empty('当前赛事没有完整的共同统计','选择双方都参加的历史赛事；不混用不同赛事计算六维图。')}`:empty('选择两位选手开始对比','从上方搜索，或在选手列表点击「+」。');shell(`${title('选手对比','PLAYER COMPARISON','同赛事、同口径对照')}${choices}${comparison}`);}
function aboutPage(){shell(`${title('数据来源与统计口径','DATA & METHODOLOGY')}<div class="about-grid">${[['可检索选手',INDEX.length],['历史战队',TEAMINDEX.length],['已统计小局',D.archive.meta.statsGames]].map(([k,v])=>`<div class="stat"><b>${num(v)}</b><small>${k}</small></div>`).join('')}</div>${panel('数据覆盖',`<div class="modal-body"><p>数据索引覆盖 2011—${CURRENT_YEAR} 年，包括主要联赛、国际赛事和来源收录的次级赛事。全量档案按需从公开数据源读取；${Object.keys(D.profiles).length} 位常用选手与 2026 世界赛 ${D.meta.games} 小局已缓存于本项目。</p><p>最新快照：<strong>${esc(D.meta.built)}</strong>。2026 世界赛覆盖到 ${D.meta.eventEnd} 决赛（赛事当地日期）；本站每天 08:17（北京时间 / 香港时间）自动检查上游快照，校验通过后发布。最近成功核验：${esc(UPDATE?.checkedAt||D.meta.retrievedAt)}。上游未发布的数据不会提前出现，GitHub 调度可能延迟。未来年份赛事不纳入已发生统计。</p><p>来源：<a href="https://riftwise.gg/stats/data" target="_blank" rel="noopener">RiftWise 公开统计数据</a>，其底层整合 Leaguepedia 与 Oracle’s Elixir。头像来自选手官方赛事资料或公开选手档案，英雄图标来自 Riot Data Dragon。RIFT INDEX 与 Riot Games、HLTV 无官方关联。</p><p>历史数据并非每局字段齐全。缺失视野或对线字段时显示「—」，完整六维图仅在六项指标都有有效样本时生成。最后战队取档案最近记录；转会信息可能滞后。</p></div>`)}${panel('六维图计算方法',`<div class="modal-body"><p>六个维度均为同一赛事、同一位置、至少 3 小局的选手中排名百分位：<code>100 ×（低于该值人数 + 0.5 × 同值人数）/ 样本人数</code>。生存维度反向计算。虚线为第 50 百分位，图形不是 Riot 官方评级或未来表现预测。</p>${DIMENSIONS.map(d=>`<div class="stat-row"><span>${d.name} / ${d.english}</span><b>${d.unit}</b></div>`).join('')}<p style="margin-top:13px">DPM、补刀和视野按有效分钟加权；对线差按有时间线数据的场次平均。不同年份的版本环境不同，跨位置和小样本结果应结合原始指标判断。</p></div>`)}${panel('更新与导出',`<div class="modal-body"><p>GitHub Actions 每天自动抓取、校验并发布；失败时保留上一份有效网站。网页每次打开都会核对发布清单与数据摘要，打开期间也会定期检查更新。<a href="https://github.com/yangkaiwen2002/rift-index-pages/actions/workflows/daily-refresh.yml" target="_blank" rel="noopener">查看更新记录 ↗</a>。网页可导出当前列表或某位选手筛选年份下的全部逐局数据。除收藏与对比选择保存在你的浏览器外，不收集账号或个人信息。</p><p><a href="https://www.hltv.org/stats/players" target="_blank" rel="noopener">版式参考 HLTV</a> · <a href="https://lolesports.com/en-US/tournament/115660540725177488/overview" target="_blank" rel="noopener">2026 Worlds 官方赛事页面</a></p></div>`)}`);}
function modal(title,content){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close-modal" aria-label="关闭">×</button></div><div class="modal-body">${content}</div>`;$('#modal').showModal();}
function csvExport(filename,headers,rows){const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const csv='\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV 已导出');}
async function render(){const token=++revision;const [path,query]=(location.hash.slice(2)||'players').split('?');route=path.split('/').map(decodeURIComponent);if(route[0]==='events'&&query){state.year=new URLSearchParams(query).get('year')||String(CURRENT_YEAR);}if(route[0]==='matches'&&query){const q=new URLSearchParams(query);state.match={year:q.get('year')||String(CURRENT_YEAR),league:q.get('league')||'all',event:q.get('event')||'all',status:q.get('status')||'all',q:q.get('q')||'',page:Math.max(1,Number(q.get('page'))||1)};}document.title=`${({'players':'选手数据库','player':'选手档案','compare':'选手对比','events':'赛事档案','teams':'战队数据库','matches':'比赛中心','about':'数据说明','saved':'我的关注'})[route[0]]||'英雄联盟数据库'} · RIFT INDEX`;try{switch(route[0]){case'players':case'saved':await playersPage();break;case'player':await playerPage(route[1]);break;case'events':await eventsPage();break;case'event':await eventPage(route[1]);break;case'teams':await teamsPage();break;case'team':await teamPage(route[1]);break;case'matches':await matchesPage();break;case'fixture':await fixturePage(route[1]);break;case'match':await matchPage(route[1]);break;case'compare':await comparePage();break;case'about':aboutPage();break;default:shell(empty('页面不存在','返回数据库继续浏览。','<a class="btn" href="#/players">返回选手数据库</a>'));}}catch(e){if(token===revision)shell(`${title('暂时无法读取数据','DATA UNAVAILABLE')}<div class="notice">${esc(e.message)}。基础数据已缓存在本地，历史档案需要访问公开数据源。</div>${empty('稍后重试','上游暂时不可用时不会显示虚构数据。','<button class="btn primary" data-action="retry">重新载入</button> <a class="btn" href="#/players">返回选手数据库</a>')}`);console.error(e);}}
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){if(e.target.dataset.fallback==='player'){e.target.removeAttribute('data-fallback');e.target.src='assets/player-placeholder.svg';e.target.alt+='（暂无可用头像）';}else if(e.target.dataset.fallback==='hide')e.target.style.visibility='hidden';}},true);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case'match-status':changeMatchFilters({status:b.dataset.status});break;case'match-reset':changeMatchFilters({year:String(CURRENT_YEAR),league:'all',event:'all',status:'all',q:''});break;case'match-prev':changeMatchFilters({page:state.match.page-1});break;case'match-next':changeMatchFilters({page:state.match.page+1});break;case'check-update':checkForUpdate(true);break;case'about':location.hash='/about';break;case'close-modal':$('#modal').close();break;case'method':modal('六维图统计口径','<p>六个维度分别使用 15 分钟经济差、分均伤害、分均补刀、击杀参与率、分均视野得分、每分钟死亡（反向）。</p><p>在当前赛事的同位置选手中，按至少 3 小局的样本计算百分位。虚线为中位线；不是官方评级。缺少任一指标时不绘制完整多边形。</p><p><a href="#/about" onclick="document.querySelector(\'#modal\').close()">查看完整数据说明 →</a></p>');break;case'retry':render();break;case'scope':state.scope=b.dataset.scope;state.page=1;state.sort=state.scope==='all'?'g':'kda';state.asc=false;render();break;case'reset':Object.assign(state,{q:'',role:'',region:'',page:1,sort:'g',asc:false});render();break;case'sort':state.asc=state.sort===b.dataset.key?!state.asc:false;state.sort=b.dataset.key;if($('#list-results'))updateList();else if(route[0]==='event')render();break;case'page-next':state.page++;updateList();break;case'page-prev':state.page--;updateList();break;case'event-next':state.eventPage++;render();break;case'event-prev':state.eventPage--;render();break;case'compare-add':{const id=b.dataset.id;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<2)state.compare.push(id);else{state.compare=[state.compare[0],id];toast('已替换第二位对比选手');}saveState();document.querySelector('.compare-tray')?.remove();app.insertAdjacentHTML('beforeend',tray());b.classList.toggle('selected',state.compare.includes(id));if(b.classList.contains('icon-btn'))b.textContent=state.compare.includes(id)?'✓':'+';break;}case'compare-remove':state.compare=state.compare.filter(x=>x!==b.dataset.id);saveState();if(route[0]==='compare')render();else{document.querySelector('.compare-tray')?.remove();app.insertAdjacentHTML('beforeend',tray());}break;case'compare-select':if(state.compare[1-Number(b.dataset.slot)]===b.dataset.id){toast('请选择两位不同的选手');break;}state.compare[Number(b.dataset.slot)]=b.dataset.id;state.compare=state.compare.filter(Boolean);saveState();render();break;case'favorite':{const id=b.dataset.id;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];saveState();b.innerHTML=icon('star')+(state.saved.includes(id)?'已关注':'关注');toast(state.saved.includes(id)?'已加入我的关注':'已取消关注');break;}case'tab':state.tab=b.dataset.tab;render();break;case'history-year':state.historyYear=b.dataset.year;render();break;case'export-list':csvExport('rift-index-players.csv',['Player','Team','Role','Games','KDA','DPM','Winrate','Scope'],playerListRows().map(p=>[p.n,p.t,p.r,p.g,p.kda,p.dpm,p.winrate,state.scope]));break;case'export-history':{const games=normalGames(await history(state.detailSlug)).filter(g=>state.historyYear==='all'||g.date.startsWith(state.historyYear));csvExport(`${state.detailSlug}-${state.historyYear}.csv`,['Date','Event','Team','Opponent','Champion','Kills','Deaths','Assists','Won','CS','Gold','Damage','Vision','Minutes','Series','Game'],games.map(g=>[g.date,g.event,g.team.n,g.opp.n,g.c,g.k,g.d,g.a,g.win,g.cs,g.gd,g.dm,g.v,g.minutes,g.id,g.number]));break;}}});
document.addEventListener('change',e=>{switch(e.target.id){case'match-year':changeMatchFilters({year:e.target.value,event:'all'});break;case'match-league':changeMatchFilters({league:e.target.value,event:'all'});break;case'match-event':changeMatchFilters({event:e.target.value});break;case'role-filter':state.role=e.target.value;state.page=1;updateList();break;case'region-filter':state.region=e.target.value;state.page=1;updateList();break;case'sort-filter':state.sort=e.target.value;state.asc=state.sort==='n';updateList();break;case'detail-event':state.detailEvent=e.target.value;render();break;case'compare-event':state.compareEvent=e.target.value;render();break;case'event-year':state.year=e.target.value;state.eventPage=1;if(location.hash.includes('?'))historyReplaceHash('#/events');render();break;}});
function historyReplaceHash(hash){window.history.replaceState(null,'',hash);}
let inputTimer;document.addEventListener('input',e=>{if(e.target.id==='match-search'){const value=e.target.value,pos=e.target.selectionStart;clearTimeout(inputTimer);inputTimer=setTimeout(()=>changeMatchFilters({q:value}).then(()=>{const input=$('#match-search');input?.focus();input?.setSelectionRange(pos,pos);}),250);}else if(e.target.id==='player-search'){state.q=e.target.value;state.page=1;updateList();}else if(e.target.id==='event-search'){state.eventsQ=e.target.value;state.eventPage=1;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{const pos=e.target.selectionStart;eventsPage().then(()=>{const input=$('#event-search');input?.focus();input?.setSelectionRange(pos,pos);});},240);}else if(e.target.id==='team-search'){state.teamQ=e.target.value;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{const pos=e.target.selectionStart;teamsPage().then(()=>{const input=$('#team-search');input?.focus();input?.setSelectionRange(pos,pos);});},240);}else if(e.target.id.startsWith('compare-search-')){const slot=e.target.id.at(-1),q=e.target.value.trim().toLowerCase(),results=$('#compare-results-'+slot);results.hidden=!q;results.innerHTML=INDEX.filter(p=>[p.n,p.real,p.t].some(s=>s?.toLowerCase().includes(q))).slice(0,8).map(p=>`<button data-action="compare-select" data-slot="${slot}" data-id="${esc(p.u)}"><strong>${esc(p.n)}</strong> <small>${esc(p.t)}</small></button>`).join('')||'<p class="hint">未找到匹配的选手</p>';}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if($('#player-search'))$('#player-search').focus();else location.hash='/players';}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);$('#modal').close();render();});
async function init(){try{const latest=await loadLatestSnapshot();D=latest.data;UPDATE=latest.update;lastUpdateCheck=Date.now();try{const overrides=await (await fetch('asset-overrides.json',{cache:'no-store'})).json();for(const [k,v]of Object.entries(overrides.teams||{}))D.teams[k]={...D.teams[k],...v};for(const [k,v]of Object.entries(overrides.players||{}))if(D.profiles[k])Object.assign(D.profiles[k],v);}catch{}if(!D.archive)throw Error('历史数据库正在同步，请稍后刷新');INDEX=D.archive.players.filter(p=>+p[4]<=CURRENT_YEAR).map(p=>({n:p[0],u:p[1]||slugify(p[0]),t:p[2],g:p[3],year:p[4],r:ROLECODE[p[5]]||'',real:p[6]}));TEAMINDEX=D.archive.teams.filter(t=>+t[3]<=CURRENT_YEAR).map(t=>({n:t[0],u:t[1]||slugify(t[0]),g:t[2],year:t[3],alias:t[4],code:t[5],region:t[6]}));EVENTINDEX=D.archive.events.filter(e=>+e[2]<=CURRENT_YEAR&&e[6]>0).map(e=>({n:e[0],u:e[1]||slugify(e[0]),year:e[2],league:e[3],date:e[5],g:e[6]}));await render();}catch(e){app.innerHTML=empty('数据库暂未就绪',esc(e.message),'<button class="btn" onclick="location.reload()">重新载入</button>');}}
init();
setInterval(()=>checkForUpdate(),300000);
window.addEventListener('focus',()=>checkForUpdate());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkForUpdate();});
